#include "config.h"

static volatile uint32_t g_millis_count = 0;

void timer_init(void) {
    /* Timer0: CTC, prescaler 64, ngat 1 ms */
    TCCR0A = (1 << WGM01);
    TCCR0B = (1 << CS01) | (1 << CS00);
    OCR0A = 249;
    TIMSK0 = (1 << OCIE0A);

    /* Timer2: CTC, prescaler 8, ngat 50 kHz */
    TCCR2A = (1 << WGM21);
    TCCR2B = (1 << CS21);
    OCR2A = 39;
    TIMSK2 = (1 << OCIE2A);
}

uint32_t millis(void) {
    uint32_t m;
    uint8_t sreg = SREG;
    cli();
    m = g_millis_count;
    SREG = sreg;
    return m;
}

void delay_ms(uint16_t ms) {
    uint32_t start = millis();
    while ((uint16_t)(millis() - start) < ms) {
        /* cho */
    }
}

ISR(TIMER0_COMPA_vect) {
    g_millis_count++;
}

ISR(TIMER2_COMPA_vect) {
    motor_step_isr();
}

#include "config.h"
#include <util/twi.h>

void i2c_init(void) {
    /* 9 xung giai phong bus theo muc 3.5 */
    PORTC &= ~((1 << PC4) | (1 << PC5));
    DDRC &= ~(1 << PC4);

    for (uint8_t i = 0; i < 9; i++) {
        DDRC |= (1 << PC5);
        for (volatile uint8_t w = 0; w < 10; w++);
        DDRC &= ~(1 << PC5);
        for (volatile uint8_t w = 0; w < 10; w++);
    }

    /* Dieu kien dung bang tay */
    DDRC |= (1 << PC4);
    for (volatile uint8_t w = 0; w < 10; w++);
    DDRC &= ~(1 << PC4);

    /* Dat phan cung I2C: 400 kHz o 16 MHz */
    TWSR = 0x00;
    TWBR = 12;
    TWCR = (1 << TWEN);
}

bool i2c_start(uint8_t addr) {
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
    while (!(TWCR & (1 << TWINT)));

    uint8_t status = TW_STATUS;
    if ((status != TW_START) && (status != TW_REP_START)) {
        return false;
    }

    TWDR = addr;
    TWCR = (1 << TWINT) | (1 << TWEN);
    while (!(TWCR & (1 << TWINT)));

    status = TW_STATUS;
    if ((status != TW_MT_SLA_ACK) && (status != TW_MR_SLA_ACK)) {
        return false;
    }

    return true;
}

bool i2c_write(uint8_t data) {
    TWDR = data;
    TWCR = (1 << TWINT) | (1 << TWEN);
    while (!(TWCR & (1 << TWINT)));

    if (TW_STATUS != TW_MT_DATA_ACK) {
        return false;
    }
    return true;
}

uint8_t i2c_read_ack(void) {
    TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWEA);
    while (!(TWCR & (1 << TWINT)));
    return TWDR;
}

uint8_t i2c_read_nack(void) {
    TWCR = (1 << TWINT) | (1 << TWEN);
    while (!(TWCR & (1 << TWINT)));
    return TWDR;
}

void i2c_stop(void) {
    TWCR = (1 << TWINT) | (1 << TWEN) | (1 << TWSTO);
}

#include "config.h"
