#include "config.h"

static volatile bool g_motor_enabled = false;
static volatile int16_t g_target_pulse_l = 0;
static volatile int16_t g_target_pulse_r = 0;

static uint16_t g_step_count_l = 0;
static uint16_t g_step_count_r = 0;
static uint16_t g_current_period_l = 0;
static uint16_t g_current_period_r = 0;

void motor_init(void) {
    /* Bang 3.1 buoc 3: Dat 4 chan dong co lam chan ra, ha hai chan xung ve 0 */
    MOTOR_DDR |= (1 << PIN_DIR_L) | (1 << PIN_DIR_R) | (1 << PIN_STEP_L) | (1 << PIN_STEP_R);
    MOTOR_PORT &= ~((1 << PIN_STEP_L) | (1 << PIN_STEP_R));
    g_motor_enabled = false;
}

void motor_enable(bool en) {
    g_motor_enabled = en;
}

void motor_set_target(int16_t pulse_l, int16_t pulse_r) {
    g_target_pulse_l = pulse_l;
    g_target_pulse_r = pulse_r;
}

int16_t motor_calc_pulse(float output) {
    (void)output;
    /* Khung doi dau ra dieu khien sang gia tri xung */
    return 0;
}

void motor_step_isr(void) {
    /* Dieu kien 1: Doc thanh ghi cong vao mot bien tam */
    uint8_t port_val = MOTOR_PORT;

    /* Dieu kien 2: Ha hai chan xung xuong muc thap ngay o dau ham */
    port_val &= ~((1 << PIN_STEP_L) | (1 << PIN_STEP_R));

    /* Dieu kien 6: Khi co cho phep chay dang tat thi dat bien ve 0 va thoat */
    if (!g_motor_enabled) {
        g_step_count_l = 0;
        g_step_count_r = 0;
        g_current_period_l = 0;
        g_current_period_r = 0;
        MOTOR_PORT = port_val;
        return;
    }

    /* Xu ly banh trai */
    if (g_target_pulse_l == 0) {
        g_step_count_l = 0;
        g_current_period_l = 0;
    } else {
        if (g_current_period_l == 0) {
            g_current_period_l = (g_target_pulse_l > 0) ? g_target_pulse_l : -g_target_pulse_l;
            if (g_target_pulse_l >= 0) {
                port_val &= ~(1 << PIN_DIR_L); /* Bang A.2: Tien = muc 0 */
            } else {
                port_val |= (1 << PIN_DIR_L);
            }
            g_step_count_l = 0;
        }
        g_step_count_l++;
        if (g_step_count_l > g_current_period_l) {
            port_val |= (1 << PIN_STEP_L);
            g_step_count_l = 0;
            g_current_period_l = (g_target_pulse_l > 0) ? g_target_pulse_l : -g_target_pulse_l;
            if (g_target_pulse_l >= 0) {
                port_val &= ~(1 << PIN_DIR_L);
            } else {
                port_val |= (1 << PIN_DIR_L);
            }
        }
    }

    /* Xu ly banh phai */
    if (g_target_pulse_r == 0) {
        g_step_count_r = 0;
        g_current_period_r = 0;
    } else {
        if (g_current_period_r == 0) {
            g_current_period_r = (g_target_pulse_r > 0) ? g_target_pulse_r : -g_target_pulse_r;
            if (g_target_pulse_r >= 0) {
                port_val |= (1 << PIN_DIR_R); /* Bang A.2: Tien = muc 1 */
            } else {
                port_val &= ~(1 << PIN_DIR_R);
            }
            g_step_count_r = 0;
        }
        g_step_count_r++;
        if (g_step_count_r > g_current_period_r) {
            port_val |= (1 << PIN_STEP_R);
            g_step_count_r = 0;
            g_current_period_r = (g_target_pulse_r > 0) ? g_target_pulse_r : -g_target_pulse_r;
            if (g_target_pulse_r >= 0) {
                port_val |= (1 << PIN_DIR_R);
            } else {
                port_val &= ~(1 << PIN_DIR_R);
            }
        }
    }

    /* Ghi bien tam ra cong dung mot lan duy nhat */
    MOTOR_PORT = port_val;
}

#include "config.h"

void uart_init(void) {
    /* Bang 3.4: Dat cong noi tiep 9600 baud */
    UBRR0H = 0;
    UBRR0L = 103;
    UCSR0C = (1 << UCSZ01) | (1 << UCSZ00);
    UCSR0B = (1 << RXEN0) | (1 << TXEN0);
}

void uart_putc(char c) {
    while (!(UCSR0A & (1 << UDRE0)));
    UDR0 = c;
}

void uart_puts(const char *s) {
    while (*s) {
        uart_putc(*s++);
    }
}

void uart_put_int(int32_t n) {
    if (n < 0) {
        uart_putc('-');
        n = -n;
    }
    char buf[12];
    uint8_t idx = 0;
    if (n == 0) {
        uart_putc('0');
        return;
    }
    while (n > 0) {
        buf[idx++] = (char)('0' + (n % 10));
        n /= 10;
    }
    while (idx > 0) {
        uart_putc(buf[--idx]);
    }
}

#include "config.h"

static robot_state_t g_state = STATE_BOOT;
static uint32_t g_last_loop_time = 0;
static uint32_t g_last_batt_time = 0;
static uint16_t g_battery_raw = 0;

static void adc_init(void) {
    /* Bang 3.4: ADMUX bat REFS0, ADCSRA bat ADEN, ADSC, ADPS2..0 */
    ADMUX = (1 << REFS0) | (ADC_PIN_BATT & 0x07);
    ADCSRA = (1 << ADEN) | (1 << ADPS2) | (1 << ADPS1) | (1 << ADPS0);
}

static uint16_t adc_read(void) {
    ADCSRA |= (1 << ADSC);
    while (ADCSRA & (1 << ADSC));
    return ADC;
}

void fsm_init(bool self_test_requested) {
    adc_init();
    if (self_test_requested) {
        g_state = STATE_SELF_TEST;
    } else {
        g_state = STATE_CALIBRATE;
    }
    g_last_loop_time = millis();
    g_last_batt_time = millis();
}

robot_state_t fsm_get_state(void) {
    return g_state;
}

void fsm_update(void) {
    uint32_t now = millis();

    /* Do pin moi 500 ms theo bang 3.3 */
    if (now - g_last_batt_time >= 500) {
        g_last_batt_time = now;
        g_battery_raw = adc_read();
        if (g_battery_raw < 420 && g_state != STATE_BOOT && g_state != STATE_SELF_TEST) {
            g_state = STATE_LOW_BATT;
            motor_enable(false);
        }
    }

    /* Vong tinh 4 ms theo muc 3.3 va NT-B */
    if (now - g_last_loop_time >= 4) {
        g_last_loop_time = now;

        /* Dao chan A1 moi vong de do bang may hien song theo NT-B */
        TEST_A1_PORT ^= (1 << PIN_TEST_A1);

        int16_t az, gx, gy;
        if (!mpu6050_read_raw(&az, &gx, &gy)) {
            g_state = STATE_ERROR;
            motor_enable(false);
            return;
        }

        float accel_angle = filter_calc_accel_angle(az);
        float current_angle = filter_update(accel_angle, gx, gy);

        switch (g_state) {
            case STATE_BOOT:
                break;

            case STATE_CALIBRATE:
                mpu6050_calibrate();
                g_state = STATE_WAIT_BALANCE;
                break;

            case STATE_WAIT_BALANCE:
                if (current_angle >= -0.5f && current_angle <= 0.5f) {
                    pid_reset();
                    motor_enable(true);
                    g_state = STATE_RUNNING;
                }
                break;

            case STATE_RUNNING:
                if (current_angle > 30.0f || current_angle < -30.0f) {
                    motor_enable(false);
                    g_state = STATE_FALLEN;
                } else {
                    float out = pid_calculate(current_angle);
                    int16_t pulse = motor_calc_pulse(out);
                    motor_set_target(pulse, pulse);
                }
                break;

            case STATE_FALLEN:
                motor_enable(false);
                if (current_angle >= -0.5f && current_angle <= 0.5f) {
                    pid_reset();
                    motor_enable(true);
                    g_state = STATE_RUNNING;
                }
                break;

            case STATE_LOW_BATT:
                motor_enable(false);
                break;

            case STATE_SELF_TEST:
                break;

            case STATE_ERROR:
                motor_enable(false);
                break;
        }
    }
}

