/* Format dong theo doi 100 ms: muc 3.10
   Trang thai, goc nghieng, gia toc tho, gia tri xung, so dong bi bo */
void uart_send_telemetry(const char *state_name, float angle, int16_t az, int16_t pulse) {
    char line[72];
    uint8_t idx = 0;

    /* Copy state_name */
    while (*state_name && idx < 20) {
        line[idx++] = *state_name++;
    }
    line[idx++] = ' ';

    /* Goc nghieng dinh dang: int_part.frac */
    int32_t ang_scaled = (int32_t)(angle * 100.0f);
    char buf[16];
    if (ang_scaled < 0) {
        line[idx++] = '-';
        ang_scaled = -ang_scaled;
    }
    int len = int_to_str(ang_scaled / 100, buf);
    for (int i = 0; i < len; i++) line[idx++] = buf[i];
    line[idx++] = '.';
    int frac = ang_scaled % 100;
    line[idx++] = (char)('0' + (frac / 10));
    line[idx++] = (char)('0' + (frac % 10));
    line[idx++] = ' ';

    /* Gia toc tho az */
    len = int_to_str((int32_t)az, buf);
    for (int i = 0; i < len; i++) line[idx++] = buf[i];
    line[idx++] = ' ';

    /* Gia tri xung pulse */
    len = int_to_str((int32_t)pulse, buf);
    for (int i = 0; i < len; i++) line[idx++] = buf[i];
    line[idx++] = ' ';

    /* So dong bi bo drop */
    len = int_to_str((int32_t)g_dropped_lines, buf);
    for (int i = 0; i < len; i++) line[idx++] = buf[i];

    line[idx++] = '\r';
    line[idx++] = '\n';
    line[idx] = '\0';

    uart_send_line(line);
}

