void uart_send_telemetry(const char *state_name, float angle, int16_t az, int16_t pulse_l, int16_t pulse_r) {
    char line[72];
    uint8_t idx = 0;

    /* Copy state_name */
    while (*state_name && idx < 20) {
        line[idx++] = *state_name++;
    }
    line[idx++] = ' ';

