int16_t motor_calc_pulse(float output) {
    if (output > 0.0f) {
        float out_nl = 405.0f - (5500.0f / (output + 9.0f));
        float p = 400.0f - out_nl;
        if (p < MOTOR_PULSE_MIN) {
            p = MOTOR_PULSE_MIN;
        } else if (p > MOTOR_PULSE_MAX) {
            p = MOTOR_PULSE_MAX;
        }
        return (int16_t)(p + 0.5f);
    } else if (output < 0.0f) {
        float out_nl = -405.0f - (5500.0f / (output - 9.0f));
        float p = -400.0f - out_nl;
        if (p > -MOTOR_PULSE_MIN) {
            p = -MOTOR_PULSE_MIN;
        } else if (p < -MOTOR_PULSE_MAX) {
            p = -MOTOR_PULSE_MAX;
        }
        return (int16_t)(p - 0.5f);
    }
    return 0;
}

